			slots[2] = (ulong)ids.Length;
			int status = EditorBindings.table.graphDocumentOpsDuplicate(slots, slots + 4);
			if (status != Bridge.OK) {
				throw Bridge.Failure(status, "GraphDocumentOps.Duplicate");
			}
			pasted = SlotValues.Array<uint>(slots + 5);
			return slots[4] != 0;
		}
	}
}
